{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "100% Crit Chance, 0% Survival Rate",
      "goal": "Artie awakens in the world of Aethelgard with a glitched Luck stat that guarantees critical hits but locks his HP at 1.",
      "chapter_role": "hook",
      "stakes_shift": "From a confused casualty of reality to a high-stakes gambler where any damage is permadeath.",
      "bridge": {
        "from_prev": "Artie's mundane life ends in a freak server-room accident.",
        "to_next": "Artie must find a way to kill the Tutorial Guardian without taking a single point of chip damage."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 2,
      "title": "The Tutorial is a Speedrun",
      "goal": "Exploit the 'Perfect Dodge' mechanic to clear the starter zone in record time and trigger a hidden achievement.",
      "chapter_role": "setup",
      "stakes_shift": "Acquiring legendary-tier starter gear makes Artie a target for envious high-level players early on.",
      "bridge": {
        "from_prev": "Artie survives the initial spawn and realizes the System rewards 'No-Hit' runs.",
        "to_next": "The achievement grants Artie a map to a forgotten dungeon that requires high movement speed."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "Glass Cannon in a Stone World",
      "goal": "Cross the treacherous Iron Peaks to reach the trade hub of Oakhaven before his 'Newbie Protection' buff expires.",
      "chapter_role": "journey",
      "stakes_shift": "Environmental hazards introduce threats that cannot be 'critically hit' or easily dodged.",
      "bridge": {
        "from_prev": "Artie leaves the tutorial zone with a unique title and a massive target on his back.",
        "to_next": "Artie arrives at Oakhaven only to find the gates barred to anyone without a guild voucher."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 9
      }
    },
    {
      "chapter_id": 4,
      "title": "The Math of Murder",
      "goal": "Enter the 'Infinite Spire' solo to prove his glass-cannon build can outpace the System's scaling difficulty.",
      "chapter_role": "trial",
      "stakes_shift": "Artie discovers that the System's 'Anti-Cheat' AI is monitoring his anomalous combat logs.",
      "bridge": {
        "from_prev": "Artie sneaks into the Spire to farm the resources needed for a guild voucher.",
        "to_next": "The AI deploys a 'Stalker' entity specifically designed to counter high-crit builds."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 11
      }
    },
    {
      "chapter_id": 5,
      "title": "Friends with Benefits (and Buffs)",
      "goal": "Recruit a disgraced shield-maiden, Silna, to act as a literal meat-shield for Artie's fragile existence.",
      "chapter_role": "alliance",
      "stakes_shift": "Artie's solo exploitation becomes a team effort, complicating his 'Hit & Run' tactics with social loyalty.",
      "bridge": {
        "from_prev": "Artie barely escapes the Stalker and realizes he needs a tank to survive the next floor.",
        "to_next": "Silna agrees to help if Artie assists her in reclaiming her stolen family heirloom from a local tyrant."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "The Raid on Red-Tier Keep",
      "goal": "Utilize a 'Damage Overflow' exploit to one-shot a regional boss that usually requires a forty-man raid.",
      "chapter_role": "confrontation",
      "stakes_shift": "The boss's death destabilizes the local political power, making Artie a kingmaker (or a criminal).",
      "bridge": {
        "from_prev": "Artie and Silna infiltrate the Keep using a combination of stealth and high-speed kiting.",
        "to_next": "The boss drops a 'World Key' that Artie wasn't supposed to find for another fifty levels."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "Level Up and Get Out",
      "goal": "Escape the collapsing Keep and the arriving System Moderators while securing the stolen treasury loot.",
      "chapter_role": "aftermath",
      "stakes_shift": "Artie officially becomes Aethelgard's most wanted 'Glitch,' forcing him into the permanent shadows.",
      "bridge": {
        "from_prev": "The World Key activates, signaling the end of the 'Tutorial Era' for the entire server.",
        "to_next": "Artie and Silna head toward the lawless 'Grey Zones' to hide and plan their next exploit."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 8
      }
    }
  ]
}

